package org.l2jmobius.gameserver.managers.phantom;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;import org.l2jmobius.commons.util.ConfigReader;
/** Stable unique cat names. Numeric profile keys are internal and never become visible suffixes. */
public final class PersonalNamePool {
 static final Store STORE=new Store(Path.of("data/L2HubPersonalNameAssignments.properties"));
 static final class Settings {
  static final ConfigReader C=new ConfigReader("config/Custom/PersonalCompanionNamePool.ini");
  static final List<String> NAMES=candidates(C.getString("PreferredNames","Bastet;Purrfect;Murmur;Nekomata;KotBayun;Felix;Pusskin;Pawdrick;Meowlin;Fluffington"),C.getString("Prefixes","Ash;Moon;Ember;Frost;Velvet;Silver;Storm;Snow;Misty;Shadow;Ivory;Amber;Onyx;Cloud;Star;Lunar;Twilight;Sable;Cinder;Dusk;Dawn;Willow;Maple;Clover;Lilac;Pearl;Jade;Copper;Golden;Silk;Opal;Ruby;Sapphire;Coal;Pepper;Cocoa;Ginger;Honey;Mochi;Toffee;Cosmic;Comet;Nova;Aurora;Dream;Sleepy;Silent;Swift;Wild;Soft;Tiny;Lucky;Noble;Brave;Fuzzy;Fluffy;Midnight;Dusky;Sunny;Smoky;Marble;Violet;Crimson;Azure"),C.getString("Suffixes","Paw;Claw;Purr;Tail;Whisker;Mew;Pounce;Fang;Paws;Mews;Kitten;Kitty;Mouser;Cat;Prowl;Whiskers;Purrs;Pouncer;Pawprint;Claws;Fangs;Feline;Tiger;Lynx;Bobcat;Panther;Leopard;Cub"));
 }
 private PersonalNamePool(){}
 static List<String> candidates(String preferred,String prefixes,String suffixes){LinkedHashSet<String> names=new LinkedHashSet<>();for(String x:preferred.split(";"))if(!x.isBlank())names.add(x.strip());for(String a:prefixes.split(";"))for(String b:suffixes.split(";")){String x=a.strip()+b.strip();if(x.matches("[A-Za-z]{1,16}"))names.add(x);}for(String x:names)if(!x.matches("[A-Za-z]{1,16}"))throw new IllegalArgumentException("Pool names must contain1-16 Latin letters: "+x);if(names.isEmpty())throw new IllegalArgumentException("Empty personal name pool");return List.copyOf(names);}
 static String name(String key,Collection<String> occupied){try{return STORE.assign(key,Settings.NAMES,new HashSet<>(occupied));}catch(IOException e){throw new IllegalStateException("Cannot preserve personal name allocation",e);}}
 static void rejectUnused(String key,String name){try{STORE.reject(key,name);}catch(IOException e){throw new IllegalStateException("Cannot retry reserved personal name",e);}}
 static final class Store {
  final Path path;final Properties values=new Properties();Store(Path p){path=p;if(Files.exists(p))try(var r=Files.newBufferedReader(p,StandardCharsets.UTF_8)){values.load(r);}catch(IOException e){throw new IllegalStateException(e);}Set<String> seen=new HashSet<>();for(String k:values.stringPropertyNames()){String v=values.getProperty(k);if(!v.matches("[A-Za-z]{1,16}")||!seen.add(v.toLowerCase(Locale.ROOT)))throw new IllegalStateException("Invalid/repeated saved personal name: "+k);}}
  synchronized String assign(String key,List<String> choices,Set<String> occupied)throws IOException {String known=values.getProperty(key);if(known!=null)return known;Set<String> used=new HashSet<>();for(String x:occupied)used.add(x.toLowerCase(Locale.ROOT));for(String k:values.stringPropertyNames())used.add(values.getProperty(k).toLowerCase(Locale.ROOT));int start=Math.floorMod(key.hashCode(),choices.size());for(int i=0;i<choices.size();i++){String name=choices.get((start+i)%choices.size());if(!used.contains(name.toLowerCase(Locale.ROOT))){Properties next=new Properties();next.putAll(values);next.setProperty(key,name);save(next);return name;}}throw new IOException("Cat name pool exhausted; extend the native name-pool INI");}
  synchronized void reject(String key,String name)throws IOException {if(!name.equals(values.getProperty(key)))return;Properties next=new Properties();next.putAll(values);next.remove(key);save(next);}
  void save(Properties next)throws IOException {Files.createDirectories(path.toAbsolutePath().getParent());Path temp=path.resolveSibling(path.getFileName()+".tmp");try(var out=Files.newBufferedWriter(temp,StandardCharsets.UTF_8)){next.store(out,"Stable personal cat-name assignments; retain across updates");}try{Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING);}values.clear();values.putAll(next);}
 }
}
